const a = [40, 5, 100];
const b = [2, undefined, 1];
const c = [
  { k: "x", n: 1 },
  { k: "y", n: 1 },
];

console.log(a.toSorted().join(","));
console.log(a.toSorted((x, y) => x - y).join(","));
console.log(b.toSorted((x, y) => y - x).map(String).join(","));
console.log(c.toSorted((x, y) => x.n - y.n).map((i) => i.k).join(","));
